SourceCode.Declaration:
/// <summary>
/// Label-preview capture parameters and auto-off logic.
/// The auto-off mechanics are a byte-for-byte mirror of the Work creation history log
/// pattern.
/// </summary>
[ExtensionOf(tableStr(WHSParameters))]
public final class WHSParameters_AAXWarehouseTools_Extension
{
    // NOTE: table-extension classes cannot declare fields/consts (compiler restriction) —
    // defaults are inlined. USER-FACING UNITS: the size/density fields store INCHES and DPI
    // (defaults: auto-off 14 days, retention 14 days, 203 DPI, 4 in wide, 6 in tall). The field
    // names keep their *Mm/*Dpmm suffix to avoid a schema change / DB sync; the accessors below
    // convert to the renderer's native mm / dots-per-mm (inch x 25.4; dpmm = round(DPI / 25.4)).
}

Method.Source:
/// <summary>
/// Auto-off window in days; unset (0) falls back to the locked default of 14.
/// </summary>
public int aaxPreviewAutoOffDays()
{
    return this.AAXPreviewAutoOffDays > 0 ? this.AAXPreviewAutoOffDays : 14;
}

/// <summary>
/// Render density in dots/mm for the renderer. The field stores DPI (default 203); this
/// converts DPI -> dpmm (203 DPI -> 8 dpmm).
/// </summary>
public int aaxPreviewDefaultDpmm()
{
    int dpi = this.AAXPreviewDefaultDpi > 0 ? this.AAXPreviewDefaultDpi : 203;
    return real2int(round(dpi / 25.4, 1.0));
}

/// <summary>
/// Render width in mm for the renderer. The field stores inches (default 4); this converts
/// inches -> mm (4 in -> 101.6 mm).
/// </summary>
public real aaxPreviewDefaultWidthMm()
{
    real widthIn = this.AAXPreviewDefaultWidthIn > 0 ? this.AAXPreviewDefaultWidthIn : 4;
    return widthIn * 25.4;
}

/// <summary>
/// Render height in mm for the renderer. The field stores inches (default 6); this converts
/// inches -> mm (6 in -> 152.4 mm).
/// </summary>
public real aaxPreviewDefaultHeightMm()
{
    real heightIn = this.AAXPreviewDefaultHeightIn > 0 ? this.AAXPreviewDefaultHeightIn : 6;
    return heightIn * 25.4;
}

/// <summary>
/// Attachment retention window in days for the purge batch; unset falls back to 14.
/// </summary>
public int aaxPreviewRetentionDays()
{
    return this.AAXPreviewRetentionDays > 0 ? this.AAXPreviewRetentionDays : 14;
}

/// <summary>
/// Sets each unset (zero) label-preview parameter field to its default, so the parameters form
/// shows sensible starting values. Units: days / days / DPI / inches / inches.
/// </summary>
public void aaxApplyPreviewDefaultsIfUnset()
{
    if (!this.AAXPreviewAutoOffDays)
    {
        this.AAXPreviewAutoOffDays = 14;
    }
    if (!this.AAXPreviewRetentionDays)
    {
        this.AAXPreviewRetentionDays = 14;
    }
    if (!this.AAXPreviewDefaultDpi)
    {
        this.AAXPreviewDefaultDpi = 203;   // DPI
    }
    if (!this.AAXPreviewDefaultWidthIn)
    {
        this.AAXPreviewDefaultWidthIn = 4;  // inches
    }
    if (!this.AAXPreviewDefaultHeightIn)
    {
        this.AAXPreviewDefaultHeightIn = 6; // inches
    }
}

/// <summary>
/// Applies the label-preview parameter defaults to a newly initialized parameters record.
/// </summary>
public void initValue()
{
    next initValue();
    this.aaxApplyPreviewDefaultsIfUnset();
}

/// <summary>
/// Sets the auto-off timestamp to now + the configured window.
/// </summary>
public void aaxInitPreviewAttachmentTurnsOff()
{
    this.AAXPreviewAttachmentTurnsOff = DateTimeUtil::addDays(
        DateTimeUtil::utcNow(),
        this.aaxPreviewAutoOffDays());
}

/// <summary>
/// Test seam replica of the internal <c>canUpdateWHSParameters</c> (internal upstream,
/// so it cannot be called from this model).
/// </summary>
private boolean aaxCanUpdateWHSParameters()
{
    return true;
}

/// <summary>
/// Lazy auto-off guard — EXACT mirror of <c>isWorkCreateHistoryLogEnabled</c>:
/// true while now is before the turns-off timestamp; an expired toggle is flipped off
/// under a pessimistic lock; a null timestamp bootstraps the window (first enable).
/// Called on both the capture hot path and the render batch.
/// </summary>
public boolean aaxIsPreviewToWorkAttachmentEnabled()
{
    if (this.AAXPreviewToWorkAttachment)
    {
        if (DateTimeUtil::utcNow() < this.AAXPreviewAttachmentTurnsOff)
        {
            return true;
        }

        boolean mustEnable = this.AAXPreviewAttachmentTurnsOff == utcDateTimeNull();

        if (this.aaxCanUpdateWHSParameters())
        {
            WHSParameters updateParameters;
            updateParameters.readPast(true);

            ttsbegin;
            select pessimisticlock firstonly updateParameters
                where updateParameters.ParametersKey == this.ParametersKey
                   && updateParameters.AAXPreviewAttachmentTurnsOff == this.AAXPreviewAttachmentTurnsOff
                   && updateParameters.AAXPreviewToWorkAttachment == true;

            if (updateParameters)
            {
                if (mustEnable)
                {
                    updateParameters.aaxInitPreviewAttachmentTurnsOff();
                }
                else
                {
                    updateParameters.AAXPreviewToWorkAttachment = NoYes::No;
                }
                updateParameters.update();
            }
            ttscommit;
        }

        return mustEnable;
    }

    return this.AAXPreviewToWorkAttachment;
}

/// <summary>
/// Toggle flipped On initializes the auto-off timestamp.
/// </summary>
public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    if (_fieldId == fieldNum(WHSParameters, AAXPreviewToWorkAttachment)
        && this.AAXPreviewToWorkAttachment)
    {
        this.aaxInitPreviewAttachmentTurnsOff();
    }
}
